"435": "Ibn Abī al-Ḥadīd a dit : Les narrations qui rapportent les mêmes paroles de l'Imām 'Alī (as) sont innombrables : «Je suis victime d'injustice depuis qu'Allah a rappelé à Lui Son Messager jusqu'à ce jour» ou encore : «Seigneur, déshonore les Quraysh car ils ont bafoué mes droits et m'ont spolié de ce qui m'est dû» ; «Châtie les Quraysh de ma part comme il se doit, car ils m'ont spolié de mon droit et ont violé le pouvoir de mon frère.» On rapporte aussi qu'alors qu'il venait d'entendre une personne crier «Je suis opprimée», il (as) dit : «Venez pour que l'on crie ensemble, car moi aussi je suis opprimé». Il a également dit : «Je vois mon héritage spolié» ; «Je suis encore brimé et privé de ce qui m'est dû.» <i>Sharḥ Nahj al-Balāgha</i>, vol. 9, p. 306",
