"596": "Les Murji'ites sont les adeptes d'une secte apparue dès les débuts de l'islam qui se fonde sur l'idée que seul Dieu peut juger ses fidèles et décider ce qui est bon et mauvais. Par conséquent, aucun croyant n'a le droit de déclarer l'autre infidèle et de l'exclure de la communauté des croyants. Ils insistent également sur le fait que la foi est plus importante que les actes et les bonnes œuvres, et que le libre arbitre de l'homme est limité. Cette secte a notamment servi à justifier une politique de tolérance à l'égard de la dynastie corrompue des Omeyyades, et est considérée comme impie par le shiisme ainsi que par l'ensemble des écoles de l'islam. (ndt)",
"597": "<i>Kanz al-'Ummāl</i>, no. 637",
"598": "<i>Biḥār al-Anwār</i>, vol. 69, p. 19, no. 2",
"599": "Voir <i>Al-Kāfī</i>, vol. 2, p. 33, le chapitre qui relate que la foi concerne l'ensemble des organes du corps.",
"600": "<i>Al-Kāfī</i>, vol. 2, p. 38, no. 7",
