"2828": "Coran, 2:278-279",
"2829": "<i>Libā</i> est le nom de la première tétée de lait que la mère donne à son enfant.",
"2830": "<i>Al-Kāfī</i>, vol. 5, p. 147, no. 11",
"2831": "Coran, 2:218",
