"2834": "<i>Al-Kāfī</i>, vol. 2, p. 68, no. 5",
"2835": "<i>Ghurar al-Ḥikam</i>, no. 2511",
"2836": "Le Retour (<i>raj'a</i>) fait partie des croyances fondamentales en le retour en ce monde de ceux qui ont eu une foi absolument pure et des personnes purement maléfiques, dans le but du rétablissement de la justice. Cela se réalisera avant le Jour de la Résurrection. (ndt)",
"2837": "<i>Biḥār al-Anwār</i>, vol. 53, p. 102, no. 125",
"2838": "<i>Ibid.</i>, p. 62, no. 52",
"2839": "<i>Ibid.</i>, p. 46, no. 19",
"2840": "<i>Ibid.</i>, p. 39, no. 1",
"2841": "Les termes de compassion et de miséricorde ont été utilisés de façon interchangeable dans cette section, étant donné qu'ils sont issus de la même racine arabe <i>r-ḥ-m</i>. La compassion réfère néanmoins davantage ici à la compassion humaine, alors que le titre de la section suivante, la miséricorde, concerne plus spécifiquement la miséricorde divine.",
