"4227": "Ce terme recouvre plusieurs significations selon les contextes : il peut désigner les gens considérés comme faibles et impuissants, mais aussi les personnes opprimées et rabaissées par les autres. Les gens considérés comme spirituellement «faibles» sont ceux qui sont incapables de réaliser les obligations religieuses du fait d'une incapacité mentale ou physique. (ndt)",
