"4572": "<i>Wasā'il al-Shī'a</i>, vol. 8, p. 606, no. 3",
"4573": "Le terme de <i>ma'rifa</i> fait ici référence à l'idée de connaissance intérieure obtenue par le cœur ou sous une forme présentielle. Elle concerne des hautes vérités telles que Dieu et l'âme, et permet ensuite de réaliser des bonnes actions et de se rapprocher d'Allah. Elle se distingue ici de la notion de <i>'ilm</i> qui dénote souvent la connaissance spéculative acquise de façon discursive, et qui ne mène pas nécessairement à une connaissance d'Allah ou à un rapprochement de Lui. (ndt)",
