"5307": "Le <i>khaṭīfa</i> est un plat à base de farine et de lait. (ndt)",
"5308": "Le <i>milbana</i> est un met à base de son de blé, de lait et de miel. (ndt)",
"5309": "<i>Biḥār al-Anwār</i>, vol. 40, p. 326, no. 7",
"5310": "<i>Nowrūz</i> est le nouvel an iranien se déroulant le jour du début du printemps, le 21 mars. (ndt)",
"5311": "<i>Kitāb man lā Yaḥḍuruhu al-Faqīh</i>, vol. 3, p. 300, no. 4073",
"5312": "<i>Ibid.</i>, p. 4074",
"5313": "<i>Biḥār al-Anwār</i>, vol. 59, p. 92, no. 1",
"5314": "<i>Wasā'il al-Shī'a</i>, vol. 7, p. 346, no. 1",
"5315": "Des Iraniens faisaient alors sans doute partie de l'armée. (ndt)",
"5316": "<i>Biḥār al-Anwār</i>, vol. 59, p. 100, no. 2 et vol. 48, p. 108, no. 9. Après avoir cité cette tradition, 'Allāma Majlisī a dit : Cette tradition contredit celles rapportées par al-Mu'allā, et semble indiquer que Nowrūz est dénué de tout contenu religieux. La tradition rapportée par al-Mu'allā a une source plus authentique et est plus connue parmi les spécialistes de <i>ḥadīth</i>. Il est possible d'interpréter cette tradition (no. 4701) comme étant basée sur une dissimulation (<i>taqiyya</i>). [L'auteur dit :] Selon nous, les deux traditions sont dépourvues des conditions d'authenticité et, comme nous l'avons précédemment cité, l'Emir des croyants (as) a dit : «Notre Nowrūz a lieu tous les jours» ; «Tout jour où l'on n'a pas désobéi à Allah est un jour de fête.»",
