"5486": "Le terme de <i>ghuluww</i> désigne plus spécifiquement les gens qui élèvent le Prophète (s) et les Imāms (as) au-dessus du statut qui leur a été conféré par Allah, en leur octroyant un statut divin. Ces personnes étaient sévèrement rejetées et condamnées par le Prophète (s) et les Imāms (as) eux-mêmes. (ndt)",
"5487": "Coran, 4:171",
