"5497": "<i>Biḥār al-Anwār</i>, vol. 25, p. 294, no. 52",
"5498": "<i>Al-mufawwiḍa</i> est le nom des adhérents à un courant de pensée qui croyait qu'après la création, Dieu livrait cette dernière à elle-même et que l'homme était totalement libre et la cause absolue de ses propres actes. Toute intervention de Dieu - hormis le fait d'être la Cause première - s'en trouvait niée. La position inverse qui croyait en la prédestination absolue de l'homme et de ses actes était défendue par le courant <i>jabariyya</i>. (ndt)",
