"5566": "<i>Kanz al-'Ummāl</i>, no. 8037",
"5567": "Le terme de <i>ghīra</i> dénote un sentiment de possession associé à un sens de l'honneur et d'estime de soi. Cette qualité, lorsqu'elle est par exemple possédée par un homme vis-à-vis de sa femme, est positive en ce qu'elle est issue d'un sens de l'honneur. Lorsqu'elle qualifie Allah, la <i>ghīra</i> fait référence au fait qu'Il mérite et exige une adoration et une loyauté exclusives de la part de Ses serviteurs. Ce terme peut également être traduit par jalousie, zèle ou ferveur selon les contextes, en ne perdant cependant pas de vue sa connotation positive. (ndt)",
"5568": "<i>Kitāb man lā Yaḥḍuruhu al-Faqīh</i>, vol. 3, p. 444, no. 4541",
