"6199": "<i>Al-Kāfī</i>, vol. 2, p. 341, no. 15",
"6200": "Coran, 6:144",
"6201": "Ibid., 39:60",
"6202": "<i>Nahj al-Balāgha</i>, sermon 147",
"6203": "<i>Qurb al-Isnād</i>, p. 133, no. 466",
"6204": "<i>Al-Kāfī</i>, vol. 2, p. 340, no. 9",
"6205": "<i>Ibid.</i>, p. 339, no. 5",
"6206": "<i>Biḥār al-Anwār</i>, vol. 72, p. 263, no. 48",
"6207": "<i>Al-Kāfī</i>, vol. 2, p. 341, no. 16",
"6208": "<i>Ibid.</i>, p. 210, no. 5",
"6209": "Ce terme exprime ici l'idée de dire une chose de telle façon qu'il est possible à l'auditeur de la comprendre et de l'interpréter différemment. (ndt)",
"6210": "Coran, 21:63",
"6211": "<i>Kanz al-'Ummāl</i>, no. 8253",
"6212": "Sheikh al-Anṣārī a commenté ainsi cette parole dans son livre <i>al-Makāsib</i>, en attirant l'attention sur l'idée de bien parler de «cet endroit particulier», qui désigne l'endroit même de la maison où la servante se tient, sinon on ne peut comprendre le sens de cette parole.",
"6213": "<i>Mustaṭrafāt al-Sarā'ir</i>, p. 137, no. 1",
"6214": "Coran, 5:41",
"6215": "<i>Nahj al-Balāgha</i>, lettre 10",
"6216": "<i>Biḥār al-Anwār</i>, vol. 72, p. 264, no: 1",
"6217": "Le terme arabe <i>karam</i> peut être traduit de différentes manières et évoque les idées de noblesse, de générosité, de libéralité, de magnificence, et toutes les hautes qualités associées à une personne ayant de nobles origines et étant issue d'une haute lignée. (ndt)",
