"6744": "Al-Aḥqāf est le pluriel de <i>ḥiqf</i> qui signifie «dune de sable». Al-Aḥqāf mentionné dans le Saint Coran est une vallée située entre Oman et les terres de Muhrah. On a également dit que cet endroit était situé entre Oman et Ḥaḍramawt. Selon Al-Ḍaḥḥāk, Al-Aḥqāf est une montagne au pays de Shām.",
