"6999": "<i>Al-Kāfī</i>, vol. 6, p. 439, no. 5. L'idée de montrer les grâces n'est bien évidemment pas un encouragement à l'ostentation mais une invitation à ne pas les cacher, à ne pas avoir une apparence misérable alors que l'on a la possibilité de s'apprêter et de donner une bonne image des croyants par sa bonne apparence et du fait des grâces dont on a été comblé. (ndt)",
