"7568": "<i>Biḥār al-Anwār</i>, vol. 78, p. 7, no. 59",
"7569": "Le terme de <i>taqwā</i> est complexe à traduire. Il est néanmoins une notion clé qui revient à de nombreuses reprises dans le Coran. Il est issu de la racine <i>waqā</i> signifiant prémunir, préserver ou encore protéger. La <i>taqwā</i> pourrait ainsi être définie comme un état intérieur propre à l'être humain qui le conduit à préserver son être de ce qui pourrait faire obstacle ou mettre en danger la réalisation de sa propre perfection et l'éloigner de sa vérité profonde, c'est-à-dire de Son créateur et de la rencontre avec Allah. (ndt)",
